 "content": "def transform(grid):
    """Complete a three-of-four set of reflected motifs in a panel grid."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Full separator lines partition the canvas into panels.
    sep_rows = [r for r in range(h) if len(set(g[r])) == 1 and g[r][0] != 0]
    sep_cols = [c for c in range(w) if all(g[r][c] == g[0][c] != 0 for r in range(h))]

    def spans(n, seps):
        out, start = [], 0
        for s in seps:
            if start < s:
                out.append((start, s))
            start = s + 1
        if start < n:
            out.append((start, n))
        return out

    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    panels = [[None for _ in cs] for _ in rs]
    for i, (r0, r1) in enumerate(rs):
        for j, (c0, c1) in enumerate(cs):
            pixels = {(r-r0, c-c0): g[r][c]
                      for r in range(r0, r1) for c in range(c0, c1) if g[r][c]}
            panels[i][j] = (r1-r0, c1-c0, pixels)

    def canonical(panel, flip_r, flip_c):
        ph, pw, pixels = panel
        return {(ph-1-r if flip_r else r, pw-1-c if flip_c else c, color)
                for (r, c), color in pixels.items()}

    # A motif's four panels are the same pattern reflected according to quadrant.
    for i in range(len(rs)-1):
        for j in range(len(cs)-1):
            block = [(i, j), (i, j+1), (i+1, j), (i+1, j+1)]
            occupied = [p for p in block if panels[p[0]][p[1]][2]]
            missing = [p for p in block if not panels[p[0]][p[1]][2]]
            if len(occupied) != 3 or len(missing) != 1:
                continue
            # Require compatible panel dimensions and a single common color.
            dims = {(panels[a][b][0], panels[a][b][1]) for a, b in occupied}
            colors = {v for a, b in occupied for v in panels[a][b][2].values()}
            if len(dims) != 1 or len(colors) != 1:
                continue
            normalized = [canonical(panels[a][b], a == i+1, b == j+1)
                          for a, b in occupied]
            if not all(x == normalized[0] for x in normalized[1:]):
                continue
            a, b = missing[0]
            ph, pw, _ = panels[a][b]
            flip_r, flip_c = a == i+1, b == j+1
            color = next(iter(colors))
            pixels = {(ph-1-r if flip_r else r, pw-1-c if flip_c else c): color
                      for r, c, _ in normalized[0]}
            r0, _ = rs[a]
            c0, _ = cs[b]
            for (r, c), value in pixels.items():
                g[r0+r][c0+c] = value
    return g
